namespace Fanex.BetList.Core.UnitTest.Builder.ChoiceBuilder
{
    using Fanex.BetList.Core.Builder.ChoiceBuilder;
    using Fanex.BetList.Core.UnitTest.Common.Templates;
    using Fanex.BetList.Core.UnitTest.Common.Enums;
    using NUnit.Framework;

    public class Choice23101Test
    {
        private ChoiceCreator _choiceCreator;

        [SetUp]
        public void Setup()
        {
            _choiceCreator = new ChoiceCreator(new Choice23101(), BetTypes.P2PTransfer);
        }

        [Test]
        public void Ticket_ShowBetTeamIsPokerGamesHyphenTransfer()
        {
            // Act
            string actualValue = _choiceCreator.GetFirstChildInnerHtml(XPathChoice.BetTeam);

            // Assert
            string expected = string.Format("{0} - {1}", TemplateChoice.PokerGames, TemplateChoice.Transfer);
            Assert.AreEqual(expected, actualValue);
        }

        [Test]
        public void Ticket_VisibleSpanBetTypeName()
        {
            // Act
            string actualHtml = _choiceCreator.GetOuterHtml(XPathChoice.BetType);

            // Assert
            string expectedHtml = string.Format(TemplateChoice.BetType, string.Empty);
            Assert.AreEqual(expectedHtml, actualHtml);
        }

        [Test]
        public void Ticket_ShowDivMatchWithHomeAndAwayTeam()
        {
            // Act
            string actualHtml = _choiceCreator.GetInnerHtml(XPathChoice.Match);

            // Assert
            string spanHomeTeam = string.Format(TemplateChoice.MatchTeamName, _choiceCreator.TicketHelperStub.GetTeamNameById(_choiceCreator.Ticket.HomeId));
            string spanAwayTeam = string.Format(TemplateChoice.MatchTeamName, _choiceCreator.TicketHelperStub.GetTeamNameById(_choiceCreator.Ticket.AwayId));
            string expectedHtml = string.Format("{0}{1}", spanHomeTeam, spanAwayTeam);
            Assert.AreEqual(expectedHtml, actualHtml);
        }

        [Test]
        public void Ticket_VisibleSpanLiveScore()
        {
            // Arrange
            _choiceCreator.Ticket.IsLive = false;

            // Act
            bool expected = false;
            bool actual = _choiceCreator.IsExist(XPathChoice.Score);

            // Assert
            Assert.AreEqual(expected, actual);
        }

        [Test]
        public void BetTeamOfTicketIsEmpty_VisibleSpanHandicap()
        {
            // Arrange
            _choiceCreator.Ticket.BetTeam = string.Empty;

            // Act
            string actualValue = _choiceCreator.GetFirstChildInnerHtml(XPathChoice.BetTeamHandicap);

            // Assert
            string expected = " ";
            Assert.AreEqual(expected, actualValue);
        }

        [Test]
        public void Ticket_ShowBetTeamClassNameIsFavorite()
        {
            // Act
            string actualValue = _choiceCreator.GetHtmlClassValue(XPathChoice.BetTeam);

            // Assert
            string expected = TemplateChoice.BLFavorite;
            Assert.AreEqual(expected, actualValue);
        }
    }
}